/**
 * The empathy-art manifest served at GET /api/v1/empathy-art (ADEV-142).
 *
 * The frames are static files under public/images/empathy-art, named by content hash, and
 * frames.json (generated by scripts/import-empathy-art.ts) describes them. `revision` is a hash
 * over the whole set, so a client refetches frames only when it changes.
 */
import { createHash } from 'node:crypto'
import framesFile from './frames.json'
import { EMPATHY_METAPHORS, EMPATHY_STATES, type EmpathyMetaphor, type EmpathyState } from './rules'

export const EMPATHY_ART_MANIFEST_VERSION = 1
export const EMPATHY_ART_PUBLIC_PATH = '/images/empathy-art'

export interface EmpathyArtFrameRecord {
  metaphor: EmpathyMetaphor
  state: EmpathyState
  file: string
  sha256: string
  bytes: number
}

export interface EmpathyArtManifest {
  version: number
  revision: string
  metaphors: readonly EmpathyMetaphor[]
  states: readonly EmpathyState[]
  frames: Array<{ metaphor: EmpathyMetaphor; state: EmpathyState; url: string; sha256: string; bytes: number }>
}

export const EMPATHY_ART_FRAMES = framesFile.frames as EmpathyArtFrameRecord[]

/** sha256 over the frames' metaphor, state and content hash, in manifest order. */
export const EMPATHY_ART_REVISION = createHash('sha256')
  .update(EMPATHY_ART_FRAMES.map(frame => `${frame.metaphor}/${frame.state}/${frame.sha256}`).join('\n'))
  .digest('hex')

export function buildEmpathyArtManifest(baseUrl: string): EmpathyArtManifest {
  const origin = baseUrl.replace(/\/+$/, '')
  return {
    version: EMPATHY_ART_MANIFEST_VERSION,
    revision: EMPATHY_ART_REVISION,
    metaphors: EMPATHY_METAPHORS,
    states: EMPATHY_STATES,
    frames: EMPATHY_ART_FRAMES.map(({ metaphor, state, file, sha256, bytes }) => ({
      metaphor,
      state,
      url: `${origin}${EMPATHY_ART_PUBLIC_PATH}/${file}`,
      sha256,
      bytes,
    })),
  }
}
